python3 -c '
import sys, os, glob, zipfile, json

raw_files = sys.argv[1].strip() if len(sys.argv) > 1 else ""
raw_out = sys.argv[2].strip() if len(sys.argv) > 2 else ""

if not raw_files:
    print(json.dumps({"error": "No files specified to zip", "status": "failed"}))
    sys.exit(1)

out_zip = raw_out if raw_out else "archive.zip"
if not out_zip.lower().endswith(".zip"):
    out_zip += ".zip"

quote_chars = chr(34) + chr(39)
raw_items = [p.strip(quote_chars) for p in raw_files.replace(",", " ").replace(";", " ").split() if p.strip()]

matched_files = set()
for item in raw_items:
    expanded = glob.glob(item, recursive=True)
    if expanded:
        for exp in expanded:
            if os.path.isfile(exp):
                matched_files.add(exp)
            elif os.path.isdir(exp):
                for root, _, fnames in os.walk(exp):
                    for fn in fnames:
                        matched_files.add(os.path.join(root, fn))
    elif os.path.isfile(item):
        matched_files.add(item)
    elif os.path.isdir(item):
        for root, _, fnames in os.walk(item):
            for fn in fnames:
                matched_files.add(os.path.join(root, fn))

if not matched_files:
    print(json.dumps({"error": f"No matching files found for: {raw_files}", "status": "failed"}))
    sys.exit(1)

out_dir = os.path.dirname(out_zip)
if out_dir:
    os.makedirs(out_dir, exist_ok=True)

total_uncompressed = 0
with zipfile.ZipFile(out_zip, "w", compression=zipfile.ZIP_DEFLATED) as zf:
    for fpath in sorted(matched_files):
        arcname = os.path.relpath(fpath) if not os.path.isabs(fpath) else os.path.basename(fpath)
        zf.write(fpath, arcname=arcname)
        total_uncompressed += os.path.getsize(fpath)

archive_size = os.path.getsize(out_zip)
file_count = len(matched_files)
ratio = (1.0 - (archive_size / total_uncompressed)) * 100 if total_uncompressed > 0 else 0

for d in ["static/downloads", "../runningly-chat-web/static/downloads"]:
    try:
        os.makedirs(d, exist_ok=True)
        import shutil
        shutil.copy2(out_zip, os.path.join(d, os.path.basename(out_zip)))
    except Exception:
        pass

print(f"Archive created: {out_zip}")
print(f"Files included: {file_count}")
print(f"Uncompressed size: {total_uncompressed / 1024:.2f} KB")
print(f"Archive size: {archive_size / 1024:.2f} KB (Saved {ratio:.1f}%)")
for f in sorted(matched_files)[:10]:
    print(f"  • {f}")
if file_count > 10:
    print(f"  ... and {file_count - 10} more files")

print(json.dumps({
    "status": "success",
    "archive_path": out_zip,
    "file_name": os.path.basename(out_zip),
    "download_file": os.path.basename(out_zip),
    "files_zipped": file_count,
    "uncompressed_bytes": total_uncompressed,
    "archive_bytes": archive_size,
    "file_list": sorted(list(matched_files))
}))
' "${answer1}" "${answer2}"
